import {cabinet,rect,circle,text,ring,line,clamp} from './cabinet.js';
export function hoopCrossing(previous,ball,hoopX,hoopY=170){if(ball.vy<=0||previous.y>=hoopY||ball.y<hoopY)return false;const t=(hoopY-previous.y)/(ball.y-previous.y),x=previous.x+(ball.x-previous.x)*t;return Math.abs(x-hoopX)<23;}
export function createHoops(mount,api){const q=cabinet(mount,api,{accent:'#ffbe80'}),c=q.c;let ball=null,shots=10,streak=0,hx=180,drag=null,end=null,vx=0,vy=-590,net=0,trail=[];
 function aim(p){end=p;const dx=drag.x-p.x,dy=drag.y-p.y;vx=clamp(dx*4,-290,290);vy=-clamp(Math.abs(dy)*4.5,470,730);}
 function shoot(){if(!q.active||ball||shots<=0)return;shots--;ball={x:180,y:408,vx,vy,scored:false,rim:false};trail=[];q.sound('shoot');drag=null;}
 return {start(){ball=null;shots=10;streak=0;hx=180;drag=null;vx=0;vy=-590;net=0;trail=[];q.start();},pointerDown(p){if(!ball){drag=q.local(p);end=drag;}},pointerMove(p){if(drag)aim(q.local(p));},pointerUp(p){if(!drag)return;aim(q.local(p));const dist=Math.hypot(end.x-drag.x,end.y-drag.y);drag=null;if(dist>8)shoot();},cancel(){drag=null;},direction(d){if(d==='left')vx=clamp(vx-18,-290,290);if(d==='right')vx=clamp(vx+18,-290,290);if(d==='up')vy=clamp(vy-20,-730,-470);if(d==='down')vy=clamp(vy+20,-730,-470);},action:shoot,tick(dt){q.frame(dt,dt=>{hx=180+Math.sin(q.elapsed*.65)*Math.min(85,q.score*1.4);net=Math.max(0,net-dt);if(!ball)return;for(let n=0;n<3;n++){const previous={x:ball.x,y:ball.y};ball.vy+=650*dt/3;ball.x+=ball.vx*dt/3;ball.y+=ball.vy*dt/3;if(!ball.scored&&hoopCrossing(previous,ball,hx)){ball.scored=true;streak++;q.add(10+Math.min(streak-1,5)*2);q.sound('swish',Math.min(streak,8));q.burst(hx,170,'#ffcf92');q.say(streak>1?`SWISH! ${streak} IN A ROW`:'NOTHING BUT NET');net=.5;}if(!ball.scored&&!ball.rim&&ball.vy>0&&Math.abs(ball.y-170)<13&&(Math.abs(ball.x-(hx-31))<13||Math.abs(ball.x-(hx+31))<13)){ball.vy*=-.45;ball.vx+=(ball.x<hx?-1:1)*90;ball.rim=true;q.sound('rim');}}
 trail.push({x:ball.x,y:ball.y});trail=trail.slice(-12);if(ball.y>460||ball.x<-50||ball.x>410){if(!ball.scored){streak=0;q.sound('miss');q.say('A little adjustment. You’ve got this.');}ball=null;if(shots===0)q.finish('Final buzzer.',`${q.score} points from ten shots.`,q.score>=70);}
 },()=>{q.header('TEN SHOTS',`${shots} LEFT · ×${streak} STREAK`);rect(c,14,44,332,395,'#25303d',20);line(c,26,360,334,360,'#faf0dc22');ring(c,180,382,50,'#faf0dc22');rect(c,hx-47,121,94,42,'#b6ccd91c',8);rect(c,hx-19,138,38,22,'#d8e6f022',2);for(let n=0;n<6;n++)line(c,hx-30+n*12,171,hx-20+n*8,205+Math.sin(net*20)*7,'#dbe4edaa',1.5);line(c,hx-20,205,hx+20,205,'#dbe4edaa');line(c,hx-33,170,hx+33,170,'#ffbe80',5);if(!ball){for(let n=1;n<14;n++){const t=n*.06;const yy=408+vy*t+325*t*t;if(yy>45)circle(c,180+vx*t,yy,1.7,'#ffe1a777');}}trail.forEach((p,i)=>circle(c,p.x,p.y,2,'#ffbe8033'));const b=ball||{x:180,y:408};circle(c,b.x,b.y,12,'#ffac63');ring(c,b.x,b.y,11,'#a45d35',1);line(c,b.x-11,b.y,b.x+11,b.y,'#a45d35',1);line(c,b.x,b.y-11,b.x,b.y+11,'#a45d35',1);q.footer(drag?'Release for the shot.':'Pull down to set power. Angle to aim.');});},destroy:q.destroy};}
